333	      { patterns: when.filesAdded, statuses: ["added"] },
334	      { patterns: when.filesRemoved, statuses: ["removed"] },
335	      { patterns: when.filesModified, statuses: ["modified"] },
336	      { patterns: when.filesChanged, statuses: ALL_STATUSES },
